package gotreesitter

import (
	"bytes"
	"strings"
	"testing"
)

func TestStructuralDensityNodeCapSmallSourceUnbounded(t *testing.T) {
	src := bytes.Repeat([]byte("x := f(a, b)\n"), 1000) // ~13KB, under 1MiB
	if _, ok := parseFullArenaStructuralDensityNodeCap(src); ok {
		t.Fatal("density cap engaged below the 1MiB threshold")
	}
}

func TestStructuralDensityNodeCapSparseGeneratedLiteralClamps(t *testing.T) {
	// Model generated sources with a giant ASCII literal and a tiny code frame.
	var b bytes.Buffer
	b.WriteString("// Code generated by a fixture generator; DO NOT EDIT.\npackage main\n\nconst data = `")
	b.Write(bytes.Repeat([]byte("x"), 2<<20))
	b.WriteString("`\n")
	src := b.Bytes()

	capNodes, ok := parseFullArenaStructuralDensityNodeCap(src)
	if !ok {
		t.Fatal("density cap did not engage on a large source")
	}
	byteEstimate := parseFullArenaInitialNodeCapacity(len(src))
	if capNodes >= byteEstimate/10 {
		t.Fatalf("sparse literal cap = %d, want well under byte estimate %d", capNodes, byteEstimate)
	}
	got := parseFullArenaNodeCapacityForSource(src, &Language{FullParseArenaDensityCapEnabled: true}, 0)
	if got > max(capNodes, nodeCapacityForClass(arenaClassFull)) {
		t.Fatalf("capacity for sparse source = %d, want <= max(cap %d, base %d)", got, capNodes, nodeCapacityForClass(arenaClassFull))
	}
}

func TestStructuralDensityNodeCapGapAlignedDenseCodeUnclamped(t *testing.T) {
	// The former 64-window sample inspected only the first half of each 32 KiB
	// chunk in this layout and therefore missed every dense operator region.
	const (
		chunks    = 64
		halfChunk = 16 << 10
	)
	src := make([]byte, 0, chunks*2*halfChunk)
	for range chunks {
		src = append(src, bytes.Repeat([]byte("x"), halfChunk)...)
		src = append(src, bytes.Repeat([]byte("a+"), halfChunk/2)...)
	}
	capNodes, ok := parseFullArenaStructuralDensityNodeCap(src)
	if !ok {
		t.Fatal("density cap did not engage on a large source")
	}
	byteEstimate := parseFullArenaInitialNodeCapacity(len(src))
	if capNodes < byteEstimate {
		t.Fatalf("gap-aligned dense cap = %d clamps below byte estimate %d", capNodes, byteEstimate)
	}
	if got := parseFullArenaNodeCapacityForSource(src, &Language{FullParseArenaDensityCapEnabled: true}, 0); got != byteEstimate {
		t.Fatalf("gap-aligned dense capacity = %d, want unchanged byte estimate %d", got, byteEstimate)
	}
}

func TestStructuralDensityNodeCapNonASCIIFailsOpen(t *testing.T) {
	src := append(bytes.Repeat([]byte("x"), 1<<20), []byte("λ")...)
	if capNodes, ok := parseFullArenaStructuralDensityNodeCap(src); ok || capNodes != 0 {
		t.Fatalf("non-ASCII density cap=(%d,%t), want fail-open", capNodes, ok)
	}
	if got, want := parseFullArenaNodeCapacityForSource(src, &Language{FullParseArenaDensityCapEnabled: true}, 0), parseFullArenaNodeCapacity(len(src), 0); got != want {
		t.Fatalf("non-ASCII capacity=%d, want unchanged baseline=%d", got, want)
	}
}

func TestStructuralDensityNodeCapUnexpectedControlFailsOpen(t *testing.T) {
	src := append(bytes.Repeat([]byte("x"), 1<<20), '\f')
	if capNodes, ok := parseFullArenaStructuralDensityNodeCap(src); ok || capNodes != 0 {
		t.Fatalf("unexpected-control density cap=(%d,%t), want fail-open", capNodes, ok)
	}
}

func TestStructuralDensityNodeCapDenseCodeUnclamped(t *testing.T) {
	// Model opGen-style dense generated code; the cap must sit above the
	// byte-length estimate so dense sources keep their preallocation.
	line := []byte("\tcase OpAMD64ADDQ:\n\t\tv.Op = OpAMD64ADDL\n\t\treturn true\n")
	src := bytes.Repeat(line, 1<<16) // ~3.3MB dense code
	capNodes, ok := parseFullArenaStructuralDensityNodeCap(src)
	if !ok {
		t.Fatal("density cap did not engage on a large source")
	}
	byteEstimate := parseFullArenaInitialNodeCapacity(len(src))
	if capNodes < byteEstimate {
		t.Fatalf("dense code cap = %d clamps below byte estimate %d; dense sources must keep their preallocation", capNodes, byteEstimate)
	}
	if got := parseFullArenaNodeCapacityForSource(src, &Language{FullParseArenaDensityCapEnabled: true}, 0); got != byteEstimate {
		t.Fatalf("capacity for dense source = %d, want unchanged byte estimate %d", got, byteEstimate)
	}
}

func TestStructuralDensityNodeCapOperatorDenseCodeUnclamped(t *testing.T) {
	tests := []struct {
		name string
		unit []byte
	}{
		{name: "addition", unit: []byte("a+")},
		{name: "bitwise-and-shifts", unit: []byte("a|a&a^a<<a>>")},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			repeats := (1 << 20) / len(test.unit)
			src := append([]byte("package p\nvar _ = "), bytes.Repeat(test.unit, repeats)...)
			src = append(src, 'a', '\n')
			if len(src) < 1024*1024 {
				t.Fatalf("dense adversarial source is only %d bytes", len(src))
			}
			capNodes, ok := parseFullArenaStructuralDensityNodeCap(src)
			if !ok {
				t.Fatal("density cap did not engage on a large source")
			}
			byteEstimate := parseFullArenaInitialNodeCapacity(len(src))
			if capNodes < byteEstimate {
				t.Fatalf("operator-dense cap = %d clamps below byte estimate %d", capNodes, byteEstimate)
			}
			if got := parseFullArenaNodeCapacityForSource(src, &Language{FullParseArenaDensityCapEnabled: true}, 0); got != byteEstimate {
				t.Fatalf("operator-dense capacity = %d, want baseline %d; underallocation would add slabs, RSS, and soft-budget charge", got, byteEstimate)
			}
		})
	}
}

func TestStructuralDensityNodeCapPreservesLearnedHint(t *testing.T) {
	var b bytes.Buffer
	b.WriteString("package main\n\nconst data = `")
	b.Write(bytes.Repeat([]byte("x"), 2<<20))
	b.WriteString("`\n")
	src := b.Bytes()

	hint := 500_000 // a previous parse on this parser really used this many nodes
	got := parseFullArenaNodeCapacityForSource(src, &Language{FullParseArenaDensityCapEnabled: true}, hint)
	if got < hint {
		t.Fatalf("capacity with learned hint = %d, want at least the hint %d", got, hint)
	}
}

func TestStructuralDensityNodeCapRequiresCertifiedProfile(t *testing.T) {
	src := append([]byte("package p\nvalue := \""), bytes.Repeat([]byte("x"), 2<<20)...)
	src = append(src, '"', '\n')
	baseline := parseFullArenaNodeCapacity(len(src), 0)
	for _, lang := range []*Language{
		nil,
		{Name: "odin"},
		{Name: "go"},
		{Name: "typescript"},
	} {
		if got := parseFullArenaNodeCapacityForSource(src, lang, 0); got != baseline {
			t.Fatalf("uncertified language %+v capacity=%d, want baseline=%d", lang, got, baseline)
		}
	}
	certified := &Language{Name: "not-a-language-name-gate", FullParseArenaDensityCapEnabled: true}
	if got := parseFullArenaNodeCapacityForSource(src, certified, 0); got >= baseline {
		t.Fatalf("certified capacity=%d, want below baseline=%d", got, baseline)
	}
}

func TestStructuralDensityByteClassifiesAllASCIIPunctuation(t *testing.T) {
	const punctuation = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
	const whitespace = "\t\n\r "
	for value := 0; value < 0x80; value++ {
		b := byte(value)
		want := strings.ContainsRune(punctuation, rune(b)) || strings.ContainsRune(whitespace, rune(b))
		if got := parseFullArenaStructuralDensityByte(b); got != want {
			t.Fatalf("byte %#02x (%q) structural=%t, want %t", b, b, got, want)
		}
	}
}
